use morphlet::import::parse_obj;
use morphlet::mesh_fabrication::{area_center, audit, signed_volume};
use morphlet::model::Mesh;
use morphlet::stl_export::repair_meshes;

const L: [[f64; 3]; 6] = [
    [0., 0., 0.],
    [3., 0., 0.],
    [3., 1., 0.],
    [1., 1., 0.],
    [1., 3., 0.],
    [0., 3., 0.],
];
const U: [[f64; 3]; 8] = [
    [0., 0., 0.],
    [3., 0., 0.],
    [3., 3., 0.],
    [2., 3., 0.],
    [2., 1., 0.],
    [1., 1., 0.],
    [1., 3., 0.],
    [0., 3., 0.],
];
// Independent decompositions into rectangles/triangles, not generated by the
// triangulator under test. L = 3*1 + 1*2 = 5, U = 3*3 - 1*2 = 7.
const L_CAP: [[u32; 3]; 4] = [[0, 1, 3], [1, 2, 3], [0, 3, 5], [3, 4, 5]];
const U_CAP: [[u32; 3]; 6] = [
    [1, 2, 4],
    [2, 3, 4],
    [0, 1, 4],
    [0, 4, 5],
    [0, 5, 7],
    [5, 6, 7],
];

fn obj(points: &[[f64; 3]], face: &[usize]) -> Vec<u8> {
    let mut text = String::new();
    for p in points {
        text.push_str(&format!("v {} {} {}\n", p[0], p[1], p[2]));
    }
    text.push('f');
    for index in face {
        text.push_str(&format!(" {}", index + 1));
    }
    text.push('\n');
    text.into_bytes()
}
fn signed_xy_area(mesh: &Mesh, triangle: [u32; 3]) -> f64 {
    let [a, b, c] = triangle.map(|v| mesh.vertices[v as usize]);
    ((b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])) * 0.5
}
fn near(actual: f64, expected: f64) {
    assert!((actual - expected).abs() < 1e-10, "{actual} != {expected}");
}
fn sides(points: &[[f64; 3]], height: f64) -> Mesh {
    let n = points.len() as u32;
    let mut mesh = Mesh {
        vertices: points.to_vec(),
        triangles: Vec::new(),
    };
    mesh.vertices
        .extend(points.iter().map(|p| [p[0], p[1], height]));
    for i in 0..n {
        let j = (i + 1) % n;
        mesh.triangles.extend([[i, j, n + j], [i, n + j, n + i]]);
    }
    mesh
}
fn open_prism(points: &[[f64; 3]], bottom: &[[u32; 3]]) -> Mesh {
    let mut mesh = sides(points, 2.);
    mesh.triangles
        .extend(bottom.iter().map(|&[a, b, c]| [c, b, a]));
    mesh
}

#[test]
fn obj_concave_faces_preserve_area_winding_and_original_vertices() {
    for (points, expected_area) in [(&L[..], 5.), (&U[..], 7.)] {
        // A fan may appear correct for a favorable first vertex. Every cyclic
        // starting point and both windings must describe the same polygon.
        for start in 0..points.len() {
            for reverse in [false, true] {
                let mut face: Vec<_> = (0..points.len())
                    .map(|i| (i + start) % points.len())
                    .collect();
                if reverse {
                    face.reverse();
                }
                let sign = if reverse { -1. } else { 1. };
                let mesh = parse_obj(&obj(points, &face), &|| false).unwrap();
                assert_eq!(mesh.triangles.len(), points.len() - 2);
                assert_eq!(mesh.vertices.len(), points.len());
                assert!(mesh.vertices.iter().all(|p| points.contains(p)));
                assert!(
                    mesh.triangles
                        .iter()
                        .all(|&t| sign * signed_xy_area(&mesh, t) > 0.)
                );
                near(area_center(&mesh, &|| false).unwrap().0, expected_area);
            }
        }
    }
}

#[test]
fn obj_rejects_crossing_nonplanar_repeated_and_invalid_faces() {
    let crossing = [
        [0., 0., 0.],
        [3., 3., 0.],
        [0., 2., 0.],
        [3., 0., 0.],
        [3., 2., 0.],
    ];
    assert!(parse_obj(&obj(&crossing, &[0, 1, 2, 3, 4]), &|| false).is_err());
    let nonplanar = [[0., 0., 0.], [2., 0., 0.], [2., 2., 0.1], [0., 2., 0.]];
    assert!(parse_obj(&obj(&nonplanar, &[0, 1, 2, 3]), &|| false).is_err());
    // A doubled bridge used to encode holes in one OBJ face is unsupported.
    assert!(parse_obj(&obj(&L, &[0, 1, 2, 3, 4, 5, 0, 3]), &|| false).is_err());
    assert!(parse_obj(&obj(&L, &[0, 1, 20]), &|| false).is_err());
    assert!(parse_obj(&obj(&L, &[0, 1, 2, 3, 4, 5]), &|| true).is_err());
}

#[test]
fn obj_rejects_a_polygon_that_collapses_during_coordinate_welding() {
    // This valid tiny triangle is above the physical area threshold, but its
    // first two vertices quantize to the same import position at 1e-6 mm.
    let narrow = [[0., 0., 0.], [0.0000004, 0., 0.], [0., 1., 0.]];
    assert!(parse_obj(&obj(&narrow, &[0, 1, 2]), &|| false).is_err());
}

#[test]
fn concave_hole_repair_uses_existing_vertices_and_analytic_prism_volume() {
    for (points, bottom, area) in [(&L[..], &L_CAP[..], 5.), (&U[..], &U_CAP[..], 7.)] {
        let input = open_prism(points, bottom);
        let old_faces = input.triangles.len();
        assert_eq!(
            audit(&input, &|| false).unwrap().boundary_edges,
            points.len()
        );
        let (output, report) = repair_meshes(std::slice::from_ref(&input)).unwrap();
        let repaired = &output[0];
        assert_eq!(repaired.vertices, input.vertices);
        assert_eq!(report.filled_holes, 1);
        assert_eq!(report.kept_open_holes, 0);
        assert_eq!(report.added_triangles, points.len() - 2);
        let cap = &repaired.triangles[old_faces..];
        assert!(cap.iter().all(|&t| signed_xy_area(repaired, t) > 0.));
        near(cap.iter().map(|&t| signed_xy_area(repaired, t)).sum(), area);
        assert!(audit(repaired, &|| false).unwrap().closed_oriented());
        near(signed_volume(repaired, &|| false).unwrap(), area * 2.);
    }
}

#[test]
fn nonplanar_holes_are_left_open_and_reported() {
    let mut input = open_prism(&L, &L_CAP);
    input.vertices[L.len() + 3][2] += 0.25;
    let (output, report) = repair_meshes(&[input.clone()]).unwrap();
    assert_eq!(output[0], input);
    assert_eq!(report.filled_holes, 0);
    assert_eq!(report.kept_open_holes, 1);
}

#[test]
fn selfcrossing_holes_are_left_open_and_reported() {
    let crossing = [[0., 0., 0.], [2., 2., 0.], [0., 2., 0.], [2., 0., 0.]];
    let input = sides(&crossing, 2.);
    let (output, report) = repair_meshes(std::slice::from_ref(&input)).unwrap();
    assert_eq!(output[0], input);
    assert_eq!(report.filled_holes, 0);
    assert_eq!(report.kept_open_holes, 2);
}

#[test]
fn nested_coplanar_boundaries_are_not_filled_as_independent_disks() {
    let input = Mesh {
        vertices: vec![
            [0., 0., 0.],
            [3., 0., 0.],
            [3., 3., 0.],
            [0., 3., 0.],
            [1., 1., 0.],
            [2., 1., 0.],
            [2., 2., 0.],
            [1., 2., 0.],
        ],
        triangles: vec![
            [0, 1, 5],
            [0, 5, 4],
            [1, 2, 6],
            [1, 6, 5],
            [2, 3, 7],
            [2, 7, 6],
            [3, 0, 4],
            [3, 4, 7],
        ],
    };
    // Planar square annulus: 3² - 1² = 8. Both loops bound the same opening;
    // making independent disks would silently fill its central hole.
    near(area_center(&input, &|| false).unwrap().0, 8.);
    let (output, report) = repair_meshes(std::slice::from_ref(&input)).unwrap();
    assert_eq!(output[0], input);
    assert_eq!(report.filled_holes, 0);
    assert_eq!(report.kept_open_holes, 2);
    assert_eq!(audit(&output[0], &|| false).unwrap().boundary_edges, 8);
}
